#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

set +x
umask 077
unset TF_CLI_ARGS TF_CLI_ARGS_init TF_CLI_ARGS_validate TF_CLI_ARGS_plan TF_CLI_ARGS_show TF_CLI_ARGS_workspace
unset TF_LOG TF_LOG_PATH TF_LOG_CORE TF_LOG_PROVIDER
TOTAL_STAGES=5
# Credentials are session-only. Do not read or persist values through the library's dotenv helpers.
ENV_FILE=/dev/null
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TF_DIR="$ROOT_DIR/infra/terraform/prod"
HELPER="$ROOT_DIR/scripts/infra-plan.mjs"
VAR_FILES=()
RECONFIGURE_BACKEND=0

while [[ $# -gt 0 ]]; do
  case "$1" in
    --reconfigure-backend)
      RECONFIGURE_BACKEND=1
      shift
      ;;
    --var-file)
      [[ $# -ge 2 && -f "$2" ]] || { say '--var-file requires an existing file.'; exit 2; }
      VAR_FILES+=("-var-file=$(cd "$(dirname "$2")" && pwd)/$(basename "$2")")
      shift 2
      ;;
    --help|-h)
      printf 'Usage: bash scripts/plan-prod.sh [--var-file FILE ...] [--reconfigure-backend]\n'
      printf 'Uses standard Terraform tfvars/TF_VAR_* inputs; explicit var files win. Never applies.\n'
      return
      ;;
    *) say 'Unknown argument. Use --help.'; exit 2 ;;
  esac
done

[[ -t 0 && -t 1 ]] || { say 'Run this interactive script yourself in a terminal.'; exit 2; }
cd "$ROOT_DIR"
stage 'Preflight and private run directory'
for tool in terraform aws node pnpm git; do
  command -v "$tool" >/dev/null 2>&1 || { say "Missing required tool: $tool"; exit 1; }
done
mkdir -p "$ROOT_DIR/.local/infra-plan"
RUN_DIR="$(mktemp -d "$ROOT_DIR/.local/infra-plan/$(date -u +%Y%m%dT%H%M%SZ)-XXXXXX")"
export RUN_DIR
trap 'rm -f "$RUN_DIR/artifact.tfvars.json" "$RUN_DIR/plan.private.json" "$RUN_DIR/aws-identity.private.json"; unset CLOUDFLARE_API_TOKEN' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
say 'This script only plans. It does not apply, push, deploy, or change GitHub secrets.'
warn 'Raw logs and the saved plan may contain secrets. Share only report.md or report.json.'
say "Run directory: $RUN_DIR"

stage 'Build the Lambda artifact'
say 'Packaging the current checkout; build output stays in the private build.log.'
if ! (unset CLOUDFLARE_API_TOKEN; pnpm --filter @recipes/api package:lambda) >"$RUN_DIR/build.log" 2>&1; then
  say "Build failed. Inspect $RUN_DIR/build.log yourself; no plan was generated."
  exit 1
fi
node "$HELPER" artifact-inputs "$ROOT_DIR/packages/api/dist/api-lambda.zip" >"$RUN_DIR/artifact.tfvars.json"

stage 'Backend and AWS identity'
BACKEND_STATE="$TF_DIR/.terraform/terraform.tfstate"
TF_BACKEND_BUCKET="${TF_BACKEND_BUCKET:-${TF_VAR_terraform_state_bucket:-}}"
if [[ -z "$TF_BACKEND_BUCKET" ]]; then
  TF_BACKEND_BUCKET="$(node "$HELPER" backend-value "$BACKEND_STATE" bucket)"
fi
while [[ -z "$TF_BACKEND_BUCKET" ]]; do
  ask TF_BACKEND_BUCKET 'Terraform S3 state bucket (existing infrastructure; see your local configuration):'
done
TF_BACKEND_PROFILE="${TF_BACKEND_PROFILE:-${AWS_PROFILE:-${TF_VAR_aws_profile:-}}}"
if [[ -z "$TF_BACKEND_PROFILE" ]]; then
  TF_BACKEND_PROFILE="$(node "$HELPER" backend-value "$BACKEND_STATE" profile)"
fi
if [[ -z "$TF_BACKEND_PROFILE" ]]; then
  ask TF_BACKEND_PROFILE 'AWS profile for backend/preflight (Enter uses the default credential chain):'
fi
AWS_ARGS=()
BACKEND_ARGS=("-backend-config=bucket=$TF_BACKEND_BUCKET")
if [[ -n "$TF_BACKEND_PROFILE" ]]; then
  AWS_ARGS+=(--profile "$TF_BACKEND_PROFILE")
  BACKEND_ARGS+=("-backend-config=profile=$TF_BACKEND_PROFILE")
fi
if ! aws sts get-caller-identity ${AWS_ARGS[@]+"${AWS_ARGS[@]}"} --output json >"$RUN_DIR/aws-identity.private.json" 2>"$RUN_DIR/aws.log"; then
  say "AWS authentication failed. Run aws sso login for your profile, then retry. Details: $RUN_DIR/aws.log"
  exit 1
fi
ACCOUNT="$(node "$HELPER" account "$RUN_DIR/aws-identity.private.json")"
say "Backend bucket: $TF_BACKEND_BUCKET"
say "Backend/preflight AWS account: $ACCOUNT"
say "Backend profile: ${TF_BACKEND_PROFILE:-default credential chain}"
warn 'Provider credentials/workspace also depend on Terraform configuration. This is not the full policy gate planned in #14.'
if [[ -n "${AWS_EXPECTED_ACCOUNT_ID:-}" && "$ACCOUNT" != "$AWS_EXPECTED_ACCOUNT_ID" ]]; then
  say 'AWS account does not match AWS_EXPECTED_ACCOUNT_ID. Stopping.'
  exit 1
fi
confirm 'Is this the intended production account and backend for a read-only plan?' || exit 1
if [[ "$RECONFIGURE_BACKEND" == 1 ]]; then
  CACHED_BUCKET="$(node "$HELPER" backend-value "$BACKEND_STATE" bucket)"
  if [[ -n "$CACHED_BUCKET" && "$CACHED_BUCKET" != "$TF_BACKEND_BUCKET" ]]; then
    say 'Refusing reconfiguration: the selected bucket differs from the cached backend. This script is not a state migration tool.'
    exit 1
  fi
  say "Cached state key: $(node "$HELPER" backend-value "$BACKEND_STATE" key)"
  say "Cached state region: $(node "$HELPER" backend-value "$BACKEND_STATE" region)"
  warn 'Reconfiguration resets local backend metadata; it does not migrate state.'
  warn 'Verify the cached key/region above still match the S3 backend in infra/terraform/prod/versions.tf.'
  confirm 'Are the bucket, state key, region, and workspace mapping unchanged? Reinitialize local metadata only?' || exit 1
  BACKEND_ARGS+=(-reconfigure)
fi

stage 'Cloudflare credentials and Terraform initialization'
if [[ -z "${CLOUDFLARE_API_TOKEN:-}" ]]; then
  say 'Use your existing Cloudflare management API token, not the smoke service token.'
  open_url 'https://dash.cloudflare.com/profile/api-tokens'
  step 'Copy your saved token from your password manager. Cloudflare cannot reveal an existing token again.'
  while [[ -z "${CLOUDFLARE_API_TOKEN:-}" ]]; do
    ask_secret CLOUDFLARE_API_TOKEN 'Paste Cloudflare API token (hidden; not saved):'
  done
fi
export CLOUDFLARE_API_TOKEN
if ! terraform -chdir="$TF_DIR" init -no-color -input=false -lockfile=readonly "${BACKEND_ARGS[@]}" >"$RUN_DIR/init.log" 2>&1; then
  say "Terraform initialization failed. Inspect $RUN_DIR/init.log yourself. No apply was attempted."
  if grep -q 'Backend configuration changed' "$RUN_DIR/init.log"; then
    say 'If only backend authentication/settings changed and the state location is unchanged, verify it and rerun with --reconfigure-backend.'
    warn 'Do not use -migrate-state to bypass this error.'
  fi
  exit 1
fi
if ! terraform -chdir="$TF_DIR" validate -no-color >"$RUN_DIR/validate.log" 2>&1; then
  say "Terraform validation failed. Inspect $RUN_DIR/validate.log yourself."
  exit 1
fi
say 'Terraform initialization and validation succeeded.'

stage 'Plan and sanitized review report'
if ! terraform -chdir="$TF_DIR" workspace show >"$RUN_DIR/workspace.log" 2>&1; then
  say "Could not identify the Terraform workspace. Inspect $RUN_DIR/workspace.log yourself."
  exit 1
fi
say "Terraform workspace: $(cat "$RUN_DIR/workspace.log")"
confirm 'Is this the intended production workspace? Continue with planning only?' || exit 1
say 'Terraform will prompt for required inputs missing from environment/tfvars.'
say 'Standard local terraform.tfvars and *.auto.tfvars are loaded automatically.'
say 'Explicit --var-file arguments override those inputs; the freshly built Lambda path/hash are pinned last.'
warn 'Terraform output below is for you. Do not paste raw output or private logs into an agent conversation.'
PLAN_STATUS=0
terraform -chdir="$TF_DIR" plan -input=true -no-color -detailed-exitcode -lock-timeout=60s \
  ${VAR_FILES[@]+"${VAR_FILES[@]}"} -var-file="$RUN_DIR/artifact.tfvars.json" -out="$RUN_DIR/plan.tfplan" \
  2>&1 | tee "$RUN_DIR/plan.log" || PLAN_STATUS=$?
if [[ "$PLAN_STATUS" != 0 && "$PLAN_STATUS" != 2 ]]; then
  say "Terraform plan failed. Inspect $RUN_DIR/plan.log yourself; no review report was generated."
  exit 1
fi
if ! terraform -chdir="$TF_DIR" show -json "$RUN_DIR/plan.tfplan" >"$RUN_DIR/plan.private.json" 2>"$RUN_DIR/show.log"; then
  say "Could not decode the saved plan. Inspect $RUN_DIR/show.log yourself."
  exit 1
fi
node "$HELPER" report "$RUN_DIR/plan.private.json" "$RUN_DIR" "$ROOT_DIR"
unset CLOUDFLARE_API_TOKEN
say "Agent-readable report: $RUN_DIR/report.md"
say "Machine-readable report: $RUN_DIR/report.json"
say "Private saved plan: $RUN_DIR/plan.tfplan"
warn 'A generated report is not approval or proof of safety. Nothing was applied.'
}

run_wizard "$@"; exit
